typedef struct { int x, y; } Point;

Point pt = {3, 4};
Point *p = &pt;

printf("%d\n", pt.x);      /* 3  — 변수는 점 */
printf("%d\n", (*p).x);    /* 3  — 역참조 후 점 */
printf("%d\n", p->x);      /* 3  — 같은 뜻, 이 표기를 쓴다 */

double dist(const Point *a, const Point *b) {
    int dx = a->x - b->x;
    int dy = a->y - b->y;
    return sqrt(dx*dx + dy*dy);
}

