typedef struct {
    char name[20];
    int score;
} Student;

Student list[3] = {
    {"김", 90},
    {"이", 85},
    {"박", 78}
};

for (int i = 0; i < 3; i++) {
    printf("%s %d\n", list[i].name, list[i].score);
}

int total = 0;
for (int i = 0; i < 3; i++) total += list[i].score;
printf("평균 %.1f\n", total / 3.0);

int findTop(const Student *arr, int n) {
    int best = 0;
    for (int i = 1; i < n; i++)
        if (arr[i].score > arr[best].score) best = i;
    return best;
}

printf("%s\n", list[findTop(list, 3)].name);   /* 김 */

